namespace sv_c687b20071eb462fbeb09ff53732b152.Services;

public class AppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Williams",
            "Dr. Patel"
        });
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateTime date)
    {
        return Task.FromResult(new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM"
        });
    }

    /// <summary>
    /// Validates patient info and appointment details server-side.
    /// Returns a dictionary of field name → error message for any failures.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(BookAppointmentModel.Email)] = "Account has outstanding balance";
        }

        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(BookAppointmentModel.Doctor)] = "Selected doctor does not accept self-pay patients";
        }

        if (timeSlot == "10:00 AM")
        {
            errors[nameof(BookAppointmentModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

public class BookAppointmentModel
{
    // Step 1
    public string PatientName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    public string Doctor { get; set; } = string.Empty;
    public DateTime? AppointmentDate { get; set; }
    public string TimeSlot { get; set; } = string.Empty;
    public string ReasonForVisit { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Components.Forms;
using sv_c687b20071eb462fbeb09ff53732b152.Services;

namespace sv_c687b20071eb462fbeb09ff53732b152.Components.Pages;

public partial class BookAppointment
{
    private BookAppointmentModel Model { get; set; } = new();
    private EditContext editContext = default!;
    private ValidationMessageStore messageStore = default!;

    private List<string> doctors = new();
    private List<string> timeSlots = new();

    private bool showStep2;
    private bool availabilityChecked;
    private bool isSubmitting;
    private bool submitted;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        messageStore = new ValidationMessageStore(editContext);
        editContext.OnFieldChanged += (_, args) =>
        {
            messageStore.Clear(args.FieldIdentifier);
            editContext.NotifyValidationStateChanged();
        };

        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        messageStore.Clear();

        var step1Valid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
        {
            messageStore.Add(editContext.Field(nameof(Model.PatientName)), "Patient Name is required.");
            step1Valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            messageStore.Add(editContext.Field(nameof(Model.Email)), "Email is required.");
            step1Valid = false;
        }
        else if (!IsValidEmail(Model.Email))
        {
            messageStore.Add(editContext.Field(nameof(Model.Email)), "Please enter a valid email address.");
            step1Valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            messageStore.Add(editContext.Field(nameof(Model.Phone)), "Phone is required.");
            step1Valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            messageStore.Add(editContext.Field(nameof(Model.InsuranceProvider)), "Insurance Provider is required.");
            step1Valid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (step1Valid)
        {
            showStep2 = true;
            availabilityChecked = false;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private async Task OnDateChanged()
    {
        if (Model.AppointmentDate.HasValue && !string.IsNullOrWhiteSpace(Model.Doctor))
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
            Model.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        messageStore.Clear();
        availabilityChecked = false;

        var step2Valid = ValidateStep2();
        editContext.NotifyValidationStateChanged();

        if (!step2Valid)
            return;

        isSubmitting = true;

        try
        {
            var serverErrors = await AppointmentService.ValidatePatientAsync(
                Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

            if (serverErrors.Count > 0)
            {
                foreach (var (field, error) in serverErrors)
                {
                    messageStore.Add(editContext.Field(field), error);
                }

                editContext.NotifyValidationStateChanged();
                return;
            }

            availabilityChecked = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private bool ValidateStep2()
    {
        var valid = true;

        if (string.IsNullOrWhiteSpace(Model.Doctor))
        {
            messageStore.Add(editContext.Field(nameof(Model.Doctor)), "Please select a doctor.");
            valid = false;
        }

        if (!Model.AppointmentDate.HasValue)
        {
            messageStore.Add(editContext.Field(nameof(Model.AppointmentDate)), "Date is required.");
            valid = false;
        }
        else if (Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            messageStore.Add(editContext.Field(nameof(Model.AppointmentDate)), "Date must be in the future.");
            valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
        {
            messageStore.Add(editContext.Field(nameof(Model.TimeSlot)), "Please select a time slot.");
            valid = false;
        }

        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
        {
            messageStore.Add(editContext.Field(nameof(Model.ReasonForVisit)), "Reason for visit is required.");
            valid = false;
        }
        else if (Model.ReasonForVisit.Length > 500)
        {
            messageStore.Add(editContext.Field(nameof(Model.ReasonForVisit)), "Reason must be 500 characters or fewer.");
            valid = false;
        }

        return valid;
    }

    private void HandleSubmit()
    {
        submitted = true;
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

